<script setup lang="ts">
import {ledgerDateRange} from '~/utils/ledgerDateRange'
const props=defineProps<{warehouseId:number;filters?:Record<string,any>}>()
const {t}=useI18n(),{bizErrorMessage}=useBizError()
const data=ref<any>(null),error=ref(''),loading=ref(false),table=ref(false)
const columns=computed(()=>[{key:'date',label:t('goods-trend.date')},{key:'total',label:t('goods.ui.onhand'),value:(row:any)=>row.coverage==='none'?null:row.total,type:'qty' as const,keepZero:true},{key:'coverage',label:t('goods-trend.coverage'),value:(row:any)=>t('goods-trend.'+(row.coverage||'none'))}])
const warehouses=useWarehouseStore()
const zone=computed(()=>warehouses.currentWarehouse?.timezone||'UTC')
const range=ref<{start_time:string;end_time:string}|null>(null)
const choose=(value:{start_time:string;end_time:string})=>{range.value=value;load()}
const recent=(days:number)=>{
 const end=ledgerDateRange('today',zone.value)!.end_time
 const start=new Date(end+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-days+1)
 choose({start_time:start.toISOString().slice(0,10),end_time:end})
}
let generation=0
const load=async()=>{const seq=++generation;data.value=null;error.value='';loading.value=true;const result=await httpRequest<any>('/api/warehouse/inventory/history/series',{params:{...props.filters,warehouse_id:props.warehouseId,stock_types:'onhand',from:range.value?.start_time,to:range.value?.end_time},headers:warehouseHeaders(props.warehouseId),onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;loading.value=false}}
watch(()=>props.warehouseId,()=>{range.value=null;load()});onMounted(load);onBeforeUnmount(()=>generation++)
const chart=computed(()=>stockTrendChart(data.value?.series||[]))
</script>
<template><WCard class="stock-trend"><header><h2>{{t('inventory-analysis.stock-trend')}}</h2><span v-if="data">{{data.from}} — {{data.to}}</span><WButton v-if="data" size="sm" variant="text" :aria-pressed="table" @click="table=!table">{{t(table?'operator-chart.chart':'operator-chart.table')}}</WButton></header><div class="trend-filters"><WButton v-for="days in [30,90]" :key="days" size="sm" @click="recent(days)">{{t('inventory-analysis.recent-days',{n:days})}}</WButton><StockReportPeriod v-if="data" :start="data.from" :end="data.to" :timezone="zone" @change="choose"/></div><p>{{t('inventory-analysis.stock-trend-help')}}</p><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="load">{{t('dn.list.retry')}}</WButton></template></WAlert><WEmptyState v-else-if="loading" compact :title="t('common.status.loading')"/><div v-else-if="table&&data" class="history-table" tabindex="0" :aria-label="t('inventory-analysis.stock-trend')"><WTable :rows="data.series||[]" :columns="columns" row-key="date"><template #cell-date="{row}"><NuxtLink v-if="row.coverage!=='none'" :to="{path:'/inventory/history',query:{...props.filters,date:row.date}}" :aria-label="t('inventory-analysis.history-on-date',{date:row.date})">{{row.date}}</NuxtLink><span v-else>{{row.date}}</span></template><template #cell-total="{row}">{{row.coverage==='none'?'—':Number(row.total).toLocaleString()}}</template></WTable></div><div v-else-if="chart" class="trend-body"><div class="plot"><div class="ticks"><span>{{chart.max.toLocaleString()}}</span><span>{{chart.min.toLocaleString()}}</span></div><svg viewBox="0 0 600 180" role="img" :aria-label="t('inventory-analysis.stock-trend')" preserveAspectRatio="none"><path d="M0 20H600 M0 90H600 M0 160H600" stroke="#EDEFF3" fill="none"/><path :d="chart.line" stroke="#7855FE" stroke-width="2" fill="none" vector-effect="non-scaling-stroke"/><circle v-for="point in chart.points" :key="point.date" :cx="point.x" :cy="point.y" r="2" fill="#7855FE"><title>{{point.date}}: {{point.total}}</title></circle></svg><div class="dates"><span>{{data.from}}</span><span>{{data.to}}</span></div></div><div class="latest"><span>{{t('goods.ui.onhand')}}</span><strong>{{chart.last==null?'—':Number(chart.last).toLocaleString()}}</strong><span>{{t('inventory-analysis.pieces')}}</span></div></div><WEmptyState v-else compact :title="t('inventory.history.none')"/></WCard></template>
<style scoped>
.trend-filters{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}a{color:var(--w-pri)}.history-table{max-height:420px;overflow:auto}.history-table:focus-visible{outline:2px solid var(--w-pri);outline-offset:2px}.history-table :deep(.w-table){min-width:0!important;width:100%}.history-table :deep(th),.history-table :deep(td){padding-left:8px;padding-right:8px;white-space:normal}.history-table :deep(td:first-child){white-space:nowrap}.stock-trend :deep(.w-card__body){padding:16px 24px 20px}header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}h2{margin:0;font-size:16px;line-height:24px;font-weight:600}header>span,p{font-size:12px;line-height:18px;color:var(--w-text-3)}p{margin:8px 0 12px}.trend-body{display:flex;align-items:center;gap:32px}.plot{flex:1;min-width:0;display:grid;grid-template-columns:44px minmax(0,1fr);gap:0 8px}.ticks{display:flex;flex-direction:column;justify-content:space-between;padding:14px 0 20px;font-size:12px;line-height:18px;color:var(--w-text-3);text-align:right}svg{width:100%;height:180px;overflow:visible}.dates{grid-column:2;display:flex;justify-content:space-between;font-size:12px;line-height:18px;color:var(--w-text-3)}.latest{display:flex;align-items:baseline;gap:6px;font-size:13px;color:var(--w-text-2)}.latest strong{font-size:20px;line-height:28px;font-weight:600;color:var(--w-text-1)}@media(max-width:600px){.trend-body{flex-direction:column;align-items:stretch;gap:16px}.latest{justify-content:flex-end}}
</style>
